def all_clauses(m):
    lits = []
    for v in range(1, m + 1):
        lits.append(v)
        lits.append(-v)
    # all clauses of length 0..2 (order-insensitive enough for coverage)
    clauses = [[]]
    for L in (1, 2):
        for combo in itertools.combinations_with_replacement(lits, L):
            clauses.append(list(combo))
    return clauses

run = passed = 0
fails = []
for m in range(0, 3):
    clauses_pool = all_clauses(m)
    # all formulas with 0..2 clauses drawn from pool
    for ncl in range(0, 3):
        for combo in itertools.combinations_with_replacement(clauses_pool, ncl):
            inst = {"num_vars": m, "clauses": [list(c) for c in combo]}
