"""Extra randomized cross-check with a smarter exact clique solver."""
import random
from test_reduce import sat_brute
from reduce import reduce
from problems import Clique


def clique_exact(instance):
    """Exact max-clique based check (recursive, pruned)."""
    Clique.validate(instance)
    n = instance["n"]
    k = instance["k"]
    if k <= 0:
        return True
    if k > n:
        return False
    adj = [set() for _ in range(n)]
    for u, v in instance["edges"]:
        adj[u].add(v)
        adj[v].add(u)

    def search(candidates, need):
        if need <= 0:
            return True
        if len(candidates) < need:
            return False
        # pick pivot-ish: simple branch on first candidate
        cand = list(candidates)
        for idx, v in enumerate(cand):
            rest = candidates & adj[v]
            if search(rest, need - 1):
                return True
            candidates = candidates - {v}
            if len(candidates) < need:
                return False
        return False

    return search(set(range(n)), k)


rng = random.Random(999)
run = passed = 0
fails = []
for _ in range(3000):
    m = rng.randint(0, 8)
    ncl = rng.randint(0, 10)
    clauses = []
    for _ in range(ncl):
        L = rng.randint(0, 4)
        clause = []
        for _ in range(L):
            if m == 0:
                break
            v = rng.randint(1, m)
            clause.append(v if rng.random() < 0.5 else -v)
        clauses.append(clause)
    inst = {"num_vars": m, "clauses": clauses}
    run += 1
    try:
        exp = sat_brute(inst)
        red = reduce(inst)
        Clique.validate(red)
        got = clique_exact(red)
    except Exception as e:
        fails.append((inst, repr(e))); continue
    if exp == got:
        passed += 1
    else:
        fails.append((inst, f"sat={exp} clique={got} red={red}"))

print(f"extra run={run} passed={passed} fails={len(fails)}")
for f in fails[:5]:
    print("  FAIL", f)
EOF
